import 'package:flutter/material.dart';
import '../api.dart';
import 'provider_agenda_screen.dart';
import 'provider_wallet_screen.dart';
import 'settings_screen.dart';
class ProviderDashboardScreen extends StatefulWidget { const ProviderDashboardScreen({super.key}); @override State<ProviderDashboardScreen> createState() => _ProviderDashboardScreenState(); }
class _ProviderDashboardScreenState extends State<ProviderDashboardScreen> { final api = JopetsApi(); List<Map<String, dynamic>> products = []; String? error; @override void initState() { super.initState(); load(); } Future<void> load() async { try { final rows = await api.marketplaceProducts(); if (mounted) setState(() => products = rows); } catch (e) { if (mounted) setState(() => error = e.toString()); } } @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Panel de proveedor'), actions: [IconButton(onPressed: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const SettingsScreen())), icon: const Icon(Icons.settings))]), body: error != null ? Center(child: Text(error!)) : products.isEmpty ? const Center(child: Text('El servidor no devolvió productos.')) : ListView.builder(padding: const EdgeInsets.all(16), itemCount: products.length, itemBuilder: (_, i) => ListTile(title: Text(products[i]['name']?.toString() ?? ''), subtitle: Text('${products[i]['price'] ?? ''} ${products[i]['currency'] ?? ''}'))), bottomNavigationBar: NavigationBar(destinations: const [NavigationDestination(icon: Icon(Icons.event), label: 'Agenda'), NavigationDestination(icon: Icon(Icons.account_balance_wallet), label: 'Billetera')], onDestinationSelected: (i) => Navigator.push(context, MaterialPageRoute(builder: (_) => i == 0 ? const ProviderAgendaScreen() : const ProviderWalletScreen())))); }
